  ns={}
  exec(s.split("with open('answer.xyz'")[0],ns)
  ats=ns['atoms']; xyz=np.array([p for e,p in ats])
  # min pair all non bonded below 1.3 excluding Cu-Br, Ti-Cp, Ti-alpha, but look
